  // /features/quotes
  "featurePage.quotes.label": "Quotes and estimates",
  "featurePage.quotes.headline": "Price the job once, and send it before you leave the driveway",
  "featurePage.quotes.oneLine": "Build a quote from your own rates, send it as a PDF in your colours, and let the client sign it online.",
  "featurePage.quotes.description": "Quoting for field-service contractors: your own rates, good-better-best options, a branded PDF, and online approval with a signature.",
  "featurePage.quotes.imageCaption": "A quote being built at the house, off the contractor's own service list and their own rates.",
  "featurePage.quotes.inlineCaption": "The same quote as the client gets it: the contractor's logo, the contractor's colour, and an Approve button at the bottom. What they saw at the moment they signed is recorded with the signature.",
  "featurePage.quotes.pain.1.pain": "The numbers get written on the back of a receipt at the house and typed up at nine at night — if you are not too tired.",
  "featurePage.quotes.pain.1.fix": "The lines come off your own price book while you are standing in the room, so the quote is finished when the walkthrough is.",
  "featurePage.quotes.pain.2.pain": "The homeowner asks what it would cost to do it properly, so you rewrite the whole thing and now there are three files and nobody knows which one they read.",
  "featurePage.quotes.pain.2.fix": "One job, three prices, one document. They pick the one they want and that is the one that becomes the job.",
